def derivative(w):
    return 2 * (w - 3)   # worked out by hand with the power rule

print(derivative(1))   # -4

def derivative(w):
    return 2 * (w - 3)

for w in [1, 3, 5]:
    print(w, derivative(w))   # 1 -4 / 3 0 / 5 4

def derivative(w):
    return 2 * (w - 3)

change_in_w = 0.1
print(derivative(1) * change_in_w)   # -0.4: about how much the loss changes
